    s=json.loads((PUBLIC/'summary.json').read_text());pre=json.loads((SRC/'preflight.json').read_text());export=json.loads((PUBLIC/'ledger-export.json').read_text());F,P,U=[s['continuation_calls'][k] for k in ['firstlex','posterior','uniform']];reductionF=100*(1-U/F);reductionP=100*(1-U/P);lines=[];add=lambda text='':lines.append(text)
